function getDefaultAsyncBatcherState() {
	return {
		errorCount: 0,
		executionCount: 0,
		failedItems: [],
		isEmpty: true,
		isExecuting: false,
		isPending: false,
		items: [],
		lastResult: void 0,
		settleCount: 0,
		size: 0,
		status: "idle",
		successCount: 0,
		totalItemsProcessed: 0,
		totalItemsFailed: 0
	};
}
